<?php $report=examStaffReport($wid,$_GET);?>
<section class="card"><h2>Teaching staff submission status</h2><p class="muted">Disable question paper notices for staff on leave or away from college. This applies across examination periods, excludes them from pending counts, and keeps their CAS account and submitted papers. Enable them when they return.</p>
<form method="get" class="filters" data-exam-status-filters><input type="hidden" name="page" value="exam_manage"><input type="hidden" name="exam_id" value="<?=$wid?>"><?php if($showDeleted):?><input type="hidden" name="show_deleted" value="1"><?php endif;?><label class="grow">Name or email<input name="teacher_search" value="<?=e($_GET['teacher_search']??'')?>"></label><label>Department<select name="teacher_department"><option value="">All departments</option><?php foreach(departments()as $dept):?><option value="<?=e($dept)?>" <?=($_GET['teacher_department']??'')===$dept?'selected':''?>><?=e($dept)?></option><?php endforeach;?></select></label><label>Programme<select name="teacher_programme"><option value="">All programmes</option><?php foreach(array_merge(examProgrammes(),['__unknown'])as $prog):?><option value="<?=e($prog)?>" <?=($_GET['teacher_programme']??'')===$prog?'selected':''?>><?=e($prog==='__unknown'?'Programme not yet recorded':$prog)?></option><?php endforeach;?></select></label><label>Status<select name="teacher_status"><option value="">All statuses</option><?php foreach(['Submitted','Not submitted']as $status):?><option <?=($_GET['teacher_status']??'')===$status?'selected':''?>><?=e($status)?></option><?php endforeach;?></select></label><label>Question paper notices<select name="teacher_notifications"><option value="">All staff</option><?php foreach(['enabled'=>'Enabled','excluded'=>'Excluded']as $key=>$label):?><option value="<?=$key?>" <?=($_GET['teacher_notifications']??'')===$key?'selected':''?>><?=$label?></option><?php endforeach;?></select></label><button>Filter</button><a class="button secondary" href="?page=exam_manage&amp;exam_id=<?=$wid?><?=$showDeleted?'&amp;show_deleted=1':''?>">Clear</a></form>
<p><b><?=$report['submitted']?> submitted</b> · <b><?=$report['pending']?> not submitted</b> · <?=$report['total']?> enabled teaching staff · <?=$report['excluded']?> excluded in the selected scope.</p><p class="muted">Submitted means at least one active paper in this examination and selected programme/department. Programme filters use programmes recorded on submissions. Staff with no recorded programme are listed under “Programme not yet recorded”.</p>
<div class="table-wrap"><table><thead><tr><th>Sl. No.</th><th>Name</th><th>Home department</th><th>Programme(s) recorded</th><th>Status</th><th>Papers submitted</th><th>Question paper notices</th></tr></thead><tbody><?php foreach($report['rows']as $i=>$row):$t=$row['user'];?><tr><td><?=($report['page']-1)*10+$i+1?></td><td><?=e($t['name'])?><small><?=e($t['email'])?></small></td><td><?=e($t['department'])?></td><td><?=e($row['programmes']?implode(', ',$row['programmes']):'Programme not yet recorded')?></td><td><span class="badge <?=$row['submitted']?'good':''?>"><?=!$row['enabled']?'Excluded':($row['submitted']?'Submitted':'Not submitted')?></span></td><td><?=e(implode(', ',array_map(fn($p)=>$p['module_code'].($p['programme']?' ('.$p['programme'].')':''),$row['papers'])))?></td><td><b><?=$row['enabled']?'Enabled':'Excluded'?></b><?php if($row['reason']):?><small><?=e($row['reason'])?></small><?php endif;?><details><summary><?=$row['enabled']?'Disable notices':'Enable notices'?></summary><form method="post"><?php csrf();?><input type="hidden" name="action" value="exam_staff_preference"><input type="hidden" name="window_id" value="<?=$wid?>"><input type="hidden" name="staff_id" value="<?=$t['id']?>"><input type="hidden" name="enabled" value="<?=$row['enabled']?'0':'1'?>"><label>Reason<input name="reason" maxlength="500" placeholder="Study leave / returned to college" required></label><button><?=$row['enabled']?'Disable':'Enable'?></button></form></details></td></tr><?php endforeach;?><?php if(!$report['rows']):?><tr><td colspan="7">No staff match these filters.</td></tr><?php endif;?></tbody></table></div>
<div class="pagination"><small><?=$report['matches']?> matching records · Page <?=$report['page']?> of <?=$report['pages']?></small><div><?php foreach(['Previous'=>-1,'Next'=>1]as $label=>$offset):$next=$report['page']+$offset;if($next<1||$next>$report['pages'])continue;$query=array_merge($_GET,['page'=>'exam_manage','exam_id'=>$wid,'teacher_page'=>$next]);?><a class="button secondary" href="?<?=e(http_build_query($query))?>"><?=$label?></a><?php endforeach;?></div></div></section>
